export default {"7.1-01": {"expr": "{1/2} ÷ {1/4}","why": "Miles per hour means miles ÷ hours.","story": [["{1/2} mile","{1/2}"],["{1/4} hour","{1/4}"]]},"7.1-02": {"expr": "{3/4} ÷ {1/2}","why": "Sugar per cup of flour means cups of sugar ÷ cups of flour.","story": [["{3/4} cup of sugar","{3/4}"],["{1/2} cup of flour","{1/2}"]]},"7.1-03": {"expr": "{2/3} ÷ {1/6}","why": "Lawns per hour means lawns ÷ hours.","story": [["{2/3} of a lawn","{2/3}"],["{1/6} hour","{1/6}"]]},"7.1-04": {"expr": "150 ÷ 6","why": "Miles per gallon means miles ÷ gallons.","story": [["150 miles","150"],["6 gallons","6"]]},"7.1-05": {"expr": "3.00 ÷ 12","why": "Price per ounce means the price ÷ the ounces.","story": [["12-ounce","12"],["§3.00","3.00"]]},"7.1-06": {"expr": "{3/5} ÷ {3/4}","why": "Wall per hour means the part of the wall ÷ hours.","story": [["{3/5} of a wall","{3/5}"],["{3/4} hour","{3/4}"]]},"7.1-07": {"expr": "{1/8} ÷ {1/3}","why": "Feet per minute means feet ÷ minutes.","story": [["{1/8} foot","{1/8}"],["{1/3} minute","{1/3}"]]},"7.1-08": {"expr": "{5/6} ÷ {1/3}","why": "Square yards per bag means square yards ÷ bags.","story": [["{5/6} square yard","{5/6}"],["{1/3} bag","{1/3}"]]},"7.1-09": {"why": "Price per pencil means the price ÷ the number of pencils.","story": [["8 pencils for §2.00","2.00 ÷ 8"],["12 pencils for §2.76","2.76 ÷ 12"]],"rates": {"per": "price ÷ pencils","rates": [{"label": "Store A","top": "2.00","bot": "8"},{"label": "Store B","top": "2.76","bot": "12"}]}},"7.1-10": {"expr": "2{1/2} ÷ {1/3}","why": "Miles per hour means miles ÷ hours.","story": [["2{1/2} miles","2{1/2}"],["{1/3} hour","{1/3}"]]},"7.2-05": {"write": "c = 8t","var": "the number of tickets","why": "Each ticket costs §8, so t tickets cost 8 times t.","story": [["§8 each","8t"]]},"7.2-07": {"prop": {"ask": "fromEq","eq": "y = 4.5x","k": "4.5"}},"7.2-10": {"prop": {"pts": [["6","81"]],"ask": "k","unit": "hour","dec": true}},"7.3-01": {"expr": "24 + 0.08 × 24","why": "Tax is 8% of the price, and 8% = 0.08. The total is the price plus the tax.","story": [["§24","24"],["8%","0.08"]]},"7.3-02": {"expr": "0.2 × 36","why": "The tip is 20% of the meal, and 20% = 0.20 = 0.2.","story": [["§36","36"],["20%","0.2"]]},"7.3-03": {"expr": "60 − 0.25 × 60","why": "25% off means take away 25% of the price, and 25% = 0.25.","story": [["§60","60"],["25%","0.25"]]},"7.3-04": {"expr": "500 × 0.03 × 4","why": "Simple interest = principal × rate × years. The rate 3% = 0.03.","story": [["§500","500"],["3%","0.03"],["4 years","4"]]},"7.3-05": {"expr": "40 + 0.35 × 40","why": "A markup adds 35% of the cost to the cost, and 35% = 0.35.","story": [["§40","40"],["35%","0.35"]]},"7.3-06": {"expr": "0.06 × 2500","why": "Commission is 6% of the sales, and 6% = 0.06.","story": [["6%","0.06"],["§2,500","2500"]]},"7.3-07": {"expr": "(65 − 50) ÷ 50","why": "Percent increase = the change ÷ the original price. Then write the decimal as a percent.","story": [["§50","50"],["§65","65"]]},"7.3-08": {"expr": "(800 − 680) ÷ 800","why": "Percent decrease = the change ÷ the original number. Then write the decimal as a percent.","story": [["800","800"],["680","680"]]},"7.3-09": {"expr": "(80 − 0.15 × 80) × 1.06","why": "First take 15% off. Then the tax adds 6%, so you pay 106% of the sale price, and 106% = 1.06.","story": [["§80","80"],["15%","0.15"],["6%","1.06"]]},"7.3-10": {"expr": "1200 + 1200 × 0.05 × 3","why": "You pay back what you borrowed plus the interest. Interest = principal × rate × years, and 5% = 0.05.","story": [["§1,200","1200"],["5%","0.05"],["3 years","3"]]},"7.3-11": {"expr": "350 − 0.02 × 350","why": "The bank keeps 2% of the check, and 2% = 0.02. You get the rest.","story": [["2%","0.02"],["§350","350"]]},"7.3-12": {"expr": "45 + 0.07 × 45 + 0.18 × 45","why": "Both the tax and the tip are a percent of the §45 bill. 7% = 0.07 and 18% = 0.18.","story": [["§45","45"],["7%","0.07"],["18%","0.18"]]},"7.4-03": {"expr": "−12 + 12","why": "Down is negative and up is positive. Add the two changes.","story": [["down 12 feet","−12"],["up 12 feet","12"]]},"7.4-07": {"expr": "−6 + 15","why": "Start at −6. Warming up adds 15.","story": [["−6°F","−6"],["warms up 15°F","15"]]},"7.4-12": {"expr": "3 − (−5)","why": "Distance is the bigger number minus the smaller number.","story": [["−5","−5"],["3","3"]]},"7.4-13": {"expr": "−2.4 − (−7.1)","why": "Distance is the bigger number minus the smaller number. −2.4 is bigger (closer to 0).","story": [["−2.4","−2.4"],["−7.1","−7.1"]]},"7.4-14": {"expr": "35 − (−120)","why": "How far apart = the higher one minus the lower one.","story": [["−120 m","−120"],["35 m","35"]]},"7.5-09": {"expr": "{3/4} ÷ {1/2}","why": "Speed is miles ÷ hours. The complex fraction has {3/4} on top and {1/2} on the bottom, and that's the same as {3/4} ÷ {1/2}.","story": [["{3/4} mile","{3/4}"],["{1/2} hour","{1/2}"]]},"7.7-01": {"simp": "p + 0.1p","var": "the old price","why": "Going up 10% means the old price plus 10% of it. 10% is 0.1, so 10% of p is 0.1p.","story": [["A price p","p"],["goes up 10%","0.1p"]],"end": "1.1p means the new price is 110% of the old price."},"7.7-02": {"simp": "p − 0.2p","var": "the price before the sale","why": "20% off means the price minus 20% of it. 20% is 0.2, so 20% of p is 0.2p.","story": [["costs p dollars","p"],["20% off","0.2p"]],"end": "0.8p means you pay 80% of the price."},"7.7-03": {"write": "2n + 5","var": "the number","why": "Twice a number n is 2n. 5 more than that means add 5.","story": [["twice a number n","2n"],["5 more","5"]]},"7.7-04": {"simp": "2(L + 4)","var": "the length","why": "Perimeter is the length plus the width, twice: 2(L + 4).","story": [["length L","L"],["width 4","4"]],"end": "2L + 8 and 2(L + 4) are the same perimeter, written two ways."},"7.7-06": {"write": "{b/4} + 3","var": "the bill","why": "Four friends split the bill, so each pays b ÷ 4. Then each adds §3.","story": [["split a bill b","{b/4}"],["§3 tip","3"]]},"7.7-08": {"write": "500 − 25m","var": "the number of minutes","why": "It starts at 500 gallons. Each minute takes away 25 gallons, so m minutes take away 25m.","story": [["500 gallons","500"],["25 gallons each minute","25m"]]},"7.7-10": {"simp": "12x + 8x","var": "the number of hats, and also of scarves","why": "x hats at §12 each cost 12x. x scarves at §8 each cost 8x. Add them.","story": [["x hats at §12 each","12x"],["x scarves at §8 each","8x"]],"end": "Each hat and scarf together cost §20, so x of each cost 20x."},"7.8-01": {"expr": "−12.40 + 30 − 3(2.75)","why": "Start with what he has, add the deposit, and take away the fee 3 times.","story": [["−§12.40","−12.40"],["deposits §30","30"],["§2.75 fee 3 times","3(2.75)"]]},"7.8-02": {"expr": "3 × 2{1/4}","why": "Triple means multiply by 3.","story": [["2{1/4} cups","2{1/4}"],["triple it","3"]]},"7.8-03": {"expr": "−4.5 − 3.2 + 6","why": "Dropped means subtract; rose means add.","story": [["−4.5°C","−4.5"],["dropped 3.2°C","3.2"],["rose 6°C","6"]]},"7.8-04": {"expr": "8 − 3 × {3/4}","why": "Start with 8 feet and take away {3/4} foot, 3 times.","story": [["8 feet","8"],["{3/4} foot three times","3 × {3/4}"]]},"7.8-06": {"expr": "15.50 × 6{1/2}","why": "Pay = pay per hour × hours.","story": [["§15.50 an hour","15.50"],["6{1/2} hours","6{1/2}"]]},"7.8-07": {"expr": "−1.35 × 5","why": "A loss is negative. It happened 5 times, so multiply.","story": [["lost §1.35","−1.35"],["5 days","5"]]},"7.8-09": {"expr": "{2/5} × 30 + 4.5","why": "{2/5} full means {2/5} of 30 gallons. Then add 4.5.","story": [["{2/5} full","{2/5}"],["30 gallons","30"],["add 4.5 gallons","4.5"]]},"7.9-09": {"eq": "25 + 15m = 130","var": "the number of months","why": "What you paid = the joining fee + §15 for each month, m.","story": [["§25 to join","25"],["§15 a month","15m"],["§130","130"]]},"7.9-10": {"eq": "3t = 12 + 18","var": "what each friend paid","why": "Each friend pays t, so together they pay 3t. That covers three §4 snacks (§12) and the §18 pizza.","story": [["Three friends","3t"],["§4 snack","12"],["§18 pizza","18"]]},"7.9-14": {"eq": "9t + 4 ≤ 40","var": "the number of tickets","why": "Tickets cost §9 each, so t tickets cost 9t. Add the popcorn. You can spend at most §40, so use ≤.","story": [["§9 each","9t"],["§4 on popcorn","4"],["You have §40","40"]]},"7.1-11": {"expr": "{3/4} ÷ {1/2}","why": "Meters per hour means meters ÷ hours.","story": [["{3/4} meter","{3/4}"],["{1/2} hour","{1/2}"]]},"7.1-12": {"expr": "{2/3} ÷ {1/6}","why": "Cups per batch means cups ÷ batches.","story": [["{2/3} cup of oats","{2/3}"],["{1/6} of a batch","{1/6}"]]},"7.1-13": {"expr": "{1/2} ÷ {1/8}","why": "Posters per minute means posters ÷ minutes.","story": [["{1/2} of a poster","{1/2}"],["{1/8} minute","{1/8}"]]},"7.1-14": {"expr": "{3/5} ÷ {3/10}","why": "Bags per whole bed means bags ÷ the part of the bed.","story": [["{3/5} bag of mulch","{3/5}"],["{3/10} of a flower bed","{3/10}"]]},"7.1-15": {"expr": "4{1/2} ÷ {3/4}","why": "Square feet per hour means square feet ÷ hours.","story": [["4{1/2} square feet","4{1/2}"],["{3/4} hour","{3/4}"]]},"7.1-16": {"expr": "5{1/4} ÷ {3/8}","why": "Miles per hour means miles ÷ hours.","story": [["5{1/4} miles","5{1/4}"],["{3/8} hour","{3/8}"]]},"7.1-17": {"why": "Price per pound means the price ÷ the pounds.","story": [["{2/3} pound of almonds for §4.80","4.80 ÷ {2/3}"],["{3/4} pound of almonds for §5.70","5.70 ÷ {3/4}"]],"rates": {"per": "price ÷ pounds","diff": true,"rates": [{"label": "Brand A","top": "4.80","bot": "{2/3}"},{"label": "Brand B","top": "5.70","bot": "{3/4}"}]}},"7.1-18": {"expr": "(2{1/2} × 3{1/5}) ÷ {2/3}","why": "First the area: length × width. Then square feet per hour means square feet ÷ hours.","story": [["2{1/2} feet","2{1/2}"],["3{1/5} feet","3{1/5}"],["{2/3} hour","{2/3}"]]},"7.1-19": {"why": "Each pump's rate is gallons ÷ minutes.","story": [["1{3/4} gallons in {5/6} minute","1{3/4} ÷ {5/6}"],["2{1/4} gallons in 1{1/8} minutes","2{1/4} ÷ 1{1/8}"]],"rates": {"per": "gallons ÷ minutes","pick": "high","word": "faster","diff": true,"diffOnly": true,"rates": [{"label": "Pump X","top": "1{3/4}","bot": "{5/6}"},{"label": "Pump Y","top": "2{1/4}","bot": "1{1/8}"}]}},"7.2-13": {"prop": {"ask": "fromEq","eq": "y = 6.5x","k": "6.5","unit": "pound"}},"7.2-16": {"why": "54 liters in 12 minutes is the point (12, 54): x is minutes, y is liters.","story": [["54 liters","54"],["12 minutes","12"]],"prop": {"pts": [["12","54"]],"ask": "eq","unit": "minute","dec": true}},"7.2-19": {"why": "{3/4} cup of cocoa goes with 2{1/2} cups of flour, the pair (2{1/2}, {3/4}): f first, then c.","story": [["{3/4} cup of cocoa powder","{3/4}"],["2{1/2} cups of flour","2{1/2}"]],"prop": {"pts": [["2{1/2}","{3/4}"]],"ask": "eq","v": "f","fy": "c","unit": "cup of flour","dec": true}},"7.2-20": {"prop": {"pts": [["4","6"]],"ask": "unit","unit": "cup of blue paint","dec": true,"unitWhy": "At x = 1 cup of blue paint, y = k = 1.5 cups of yellow paint. That's the unit rate."}},"7.3-13": {"expr": "0.08 × 60","why": "The tax is 8% of the price, and 8% = 0.08.","story": [["§60","60"],["8%","0.08"]]},"7.3-14": {"expr": "500 × 0.04 × 2","why": "Simple interest = principal × rate × years. The rate 4% = 0.04.","story": [["§500","500"],["4%","0.04"],["2 years","2"]]},"7.3-15": {"expr": "45 − 0.2 × 45","why": "A 20% markdown takes away 20% of the price, and 20% = 0.2.","story": [["§45","45"],["20%","0.2"]]},"7.3-16": {"expr": "68 + 0.05 × 68 + 0.15 × 68","why": "The tax and the tip are both a percent of the §68 bill. 5% = 0.05 and 15% = 0.15.","story": [["§68.00","68"],["5%","0.05"],["15%","0.15"]]},"7.3-17": {"expr": "(52 − 40) ÷ 40","why": "Percent increase = the change ÷ the original number. Then write the decimal as a percent.","story": [["40 members","40"],["52 members","52"]]},"7.3-18": {"expr": "0.035 × 240000","why": "The commission is 3.5% of the price, and 3.5% = 0.035.","story": [["3.5%","0.035"],["§240,000","240000"]]},"7.3-19": {"expr": "(180 + 0.4 × 180) × 0.75","why": "First add the 40% markup. 25% off means you pay 75% of the marked-up price, and 75% = 0.75.","story": [["§180","180"],["40%","0.4"],["25% off","0.75"]]},"7.3-20": {"eq": "0.85p = 102","var": "the original price","why": "After 15% off you pay 85% of the original price: 100% − 15% = 85% = 0.85. So 0.85 of the original price, p, is §102.","story": [["15% discount","0.85p"],["§102","102"]]},"7.3-21": {"eq": "1200 + 72t = 1416","var": "the number of years","why": "Each year's interest is 6% of §1,200: 0.06 × 1,200 = §72. What she pays back = what she borrowed + §72 for each year, t.","story": [["§1,200","1200"],["6%","72t"],["§1,416","1416"]]},"7.4-30": {"expr": "−4.5 + 11.2 − 8.9","why": "Start at −4.5. Rising 11.2 degrees adds 11.2. Dropping 8.9 degrees subtracts 8.9.","story": [["−4.5 degrees","−4.5"],["rose 11.2 degrees","11.2"],["dropped 8.9 degrees","8.9"]]},"7.4-32": {"expr": "5 × (−2.40)","why": "Losing §2.40 is a change of −2.40. It happens 5 times, so multiply 5 by −2.40.","story": [["loses §2.40","−2.40"],["5 days","5"]]},"7.5-13": {"expr": "{3/5} ÷ {9/10}","why": "A complex fraction is a fraction divided by a fraction. Divide {3/5} by {9/10}."},"7.5-15": {"expr": "125.4 + 48.6 − 3 × 62.5","why": "Start at 125.4. Climbing adds 48.6. Descending 3 sections of 62.5 takes away 3 × 62.5.","story": [["125.4 feet","125.4"],["climbs 48.6 feet","48.6"],["3 equal sections of 62.5 feet","3 × 62.5"]]},"7.5-17": {"expr": "(18{3/4} − 9 × 1{1/4}) ÷ {5/8}","why": "9 loaves use 9 × 1{1/4} pounds. Take that from 18{3/4} to get what's left, then see how many {5/8}-pound batches fit in it.","story": [["18{3/4} pounds","18{3/4}"],["1{1/4} pounds","1{1/4}"],["{5/8} pound","{5/8}"],["9 loaves","9"]]},"7.5-19": {"eq": "s − 42.50 + 115.00 − 28.75 − 19.25 = 84.50","var": "the starting balance","why": "Start with the unknown balance, s. Add each transaction to it. What's left at the end is §84.50.","story": [["-§42.50","42.50"],["+§115.00","115.00"],["-§28.75","28.75"],["-§19.25","19.25"],["§84.50","84.50"]]},"7.6-17": {"simp": "(2.5x + 4) + (1.5x − 1)","var": "the unknown in the side lengths","wrap": 2,"why": "A rectangle's perimeter is 2 times (length + width). Add the length and width first.","wrapWhy": "The perimeter is 2 times that sum. Keep it in factored form: 2 in front, the sum in parentheses.","story": [["(2.5x + 4) meters","2.5x"],["(1.5x − 1) meters","1.5x"]]},"7.6-19": {"eq": "−6k = 18","var": "the number in front","why": "k(4x − 6) + 2x = 4kx − 6k + 2x. Its number without x is −6k. To match −10x + 18, that number has to be 18.","story": [["k(4x − 6)","−6k"],["18","18"]]},"7.7-11": {"simp": "p − 0.15p","var": "the regular price","why": "Discounted by 15% means the price minus 15% of it. 15% is 0.15, so 15% of p is 0.15p.","story": [["regular price p","p"],["discounted by 15%","0.15p"]],"end": "p − 0.15p and 0.85p are the same sale price, written two ways."},"7.7-12": {"simp": "d + 0.07d","var": "the purchase before tax","why": "The tax adds 7% of d. 7% is 0.07, so the total is d + 0.07d.","story": [["purchase of d dollars","d"],["7% sales tax","0.07d"]],"end": "1.07d means the total is 107% of the purchase."},"7.7-13": {"simp": "4(s + 2)","var": "the old side length","why": "Each new side is s + 2. A square has 4 equal sides, so the perimeter is 4 times (s + 2).","story": [["increased by 2 inches","2"],["A square","4(s + 2)"]],"end": "4(s + 2) and 4s + 8 are the same perimeter, written two ways."},"7.7-17": {"simp": "0.9(1.3w)","var": "the wholesale price","why": "A 30% markup makes the price w + 0.3w = 1.3w. A 10% discount leaves 90% of that price, so multiply by 0.9.","story": [["marks up wholesale book prices w by 30%","1.3w"],["10% loyalty discount","0.9(1.3w)"]],"end": "1.17w is 117% of w, so it's a 17% increase overall."},"7.7-19": {"simp": "0.92(0.92p)","var": "the starting population","why": "Each 8% decrease leaves 92% of what was there. After last year the population is 0.92p. This year's 8% comes off 0.92p, not p, so multiply by 0.92 again.","story": [["decreased by 8% last year","0.92p"],["decreased by 8% again this year","0.92(0.92p)"]],"end": "0.8464p is about 84.6% of p. The student took 8% off the original p twice."},"7.9-20": {"eq": "4.50 + 3.75g = 19.50","var": "the number of games","why": "What Jordan spends = the shoe rental + §3.75 for each game, g.","story": [["§4.50 for shoe rental","4.50"],["§3.75 per game","3.75g"],["§19.50 total","19.50"]]},"7.9-21": {"eq": "2(9) + 2(x + 5) = 54","var": "the number in the length","why": "Perimeter = 2 widths + 2 lengths. The width is 9 and the length is x + 5.","story": [["perimeter of 54 cm","54"],["width is 9 cm","2(9)"],["(x + 5) cm","2(x + 5)"]]},"7.9-22": {"eq": "22 + 4.50n ≤ 85","var": "the number of notebooks","whole": "notebooks","why": "The backpack plus §4.50 for each notebook, n, can be at most §85, so use ≤.","story": [["§85 to spend","85"],["§22 backpack","22"],["§4.50 each","4.50n"]]},"7.9-25": {"eq": "65c + 185 ≤ 1200","var": "the number of crates","whole": "crates","why": "The crates weigh 65c, plus the operator. The total can be at most 1,200 pounds, so use ≤.","story": [["maximum weight limit of 1,200 pounds","1200"],["185 pounds","185"],["each crate weighs 65 pounds","65c"]]},"8.11-13": {"eq": "20 + 15m = 50 + 10m","var": "the number of months","why": "Each gym's cost is its joining fee plus its monthly price times the months, m. The costs are the same, so set them equal.","story": [["§20 to join","20"],["§15 a month","15m"],["§50 to join","50"],["§10 a month","10m"]]},"8.11-14": {"eq": "2w + 2(w + 5) = 46","var": "the width","why": "Let w be the width. The length is 5 more, w + 5. Perimeter = 2 widths + 2 lengths.","story": [["5 more than its width","2(w + 5)"],["perimeter is 46","46"]],"then": [{"label": "Length","expr": "w + 5"}]},"8.11-15": {"eq": "x + (x + 3) + (2x − 1) = 30","var": "the shortest side","why": "The perimeter is all three sides added together.","story": [["x + 3","x + 3"],["2x − 1","2x − 1"],["perimeter is 30","30"]],"then": [{"label": "Longest side, 2x − 1","expr": "2x − 1"}]},"8.15-05": {"cmp": {"ask": "m","fns": [{"label": "Function A","eq": "y = 3x + 2","m": "3","b": "2"},{"label": "Function B","pts": [["0","5"],["2","9"]]}]}},"8.15-06": {"cmp": {"ask": "b","fns": [{"label": "Function A","eq": "y = 3x + 2","m": "3","b": "2"},{"label": "Function B","pts": [["0","5"],["2","9"]]}]}},"8.15-08": {"why": "Saving faster means more money each week: the bigger rate of change.","story": [["§10 a week","10"],["starting with §25","25"],["y = 12x","12"]],"cmp": {"ask": "m","fns": [{"label": "Ana","m": "10","b": "25","why": "Ana adds §10 each week, so m = 10. She starts with §25."},{"label": "Ben","eq": "y = 12x","m": "12","b": "0"}]}},"8.16-01": {"why": "The pool starts at 500 gallons and loses 20 each minute.","story": [["500 gallons","500"],["drains 20 gallons a minute","−20"]],"line": {"m": "−20","b": "500","bFirst": true,"mWhy": "It drains 20 gallons each minute, so the rate of change is −20.","bWhy": "It starts with 500 gallons, so b = 500.","eqWhy": "Gallons left = the 500 it starts with, minus 20 for each minute x."}},"8.16-05": {"why": "The cost goes up §40 every month. The §100 is paid once, at the start.","story": [["§40 a month","40"],["§100 for the phone","100"]],"line": {"m": "40","b": "100","ask": "mb","mWhy": "§40 each month is the rate of change.","bWhy": "§100 at the start, before any months, is the initial value."}},"8.16-06": {"why": "The candle starts at 12 inches and gets 1.5 inches shorter each hour.","story": [["12 in tall","12"],["burns 1.5 in per hour","−1.5"]],"line": {"m": "−1.5","b": "12","v": "t","fy": "h","bFirst": true,"mWhy": "It burns 1.5 inches each hour, so the rate of change is −1.5.","bWhy": "It starts 12 inches tall, so b = 12.","eqWhy": "Height = the 12 inches it starts with, minus 1.5 for each hour t."}},"8.25-19": {"expr": "(180 − 42 − 61) − 53","why": "The angles of the big triangle JKL add up to 180°, so angle K = 180 − 42 − 61. Segment KM splits angle K into JKM and LKM, so take away 53.","story": [["42°","42"],["61°","61"],["53°","53"]]},"8.14-16": {"expr": "(−2(4) + 7) + ((−3)² − 3)","why": "Put 4 in for x in p, and −3 in for x in q. Then add the two outputs.","story": [["p(4)","−2(4) + 7"],["q(−3)","(−3)² − 3"]]},"8.14-17": {"expr": "(120 − 4.5 × 4) − (120 − 4.5 × 12)","why": "Find what's left at t = 4 and at t = 12. What drained out is the first amount minus the second.","story": [["t = 4","4"],["t = 12","12"],["120 − 4.5t","120"]]},"8.15-10": {"cmp": {"ask": "b","fns": [{"label": "Function A","eq": "y = 3x + 4","m": "3","b": "4"},{"label": "Function B","m": "5","b": "2","why": "Function B's slope is 5 and its y-intercept is 2."}]}},"8.15-13": {"cmp": {"ask": "steep","fns": [{"label": "Linear Function 1","eq": "y = −2x + 8","m": "−2","b": "8"},{"label": "Linear Function 2","pts": [["0","6"],["2","0"]]}]}},"8.15-14": {"cmp": {"ask": "both","fns": [{"label": "Function P","eq": "y = 4x − 3","m": "4","b": "−3"},{"label": "Function Q","pts": [["1","3"],["3","11"]]}]}},"8.15-15": {"line": {"pts": [["2","10"],["5","19"]],"ask": "at","at": "9","atName": "k","end": "Any other k would change the rate of change, so the points would not be on one line."}},"8.15-16": {"eq": "0.5x + 6 = 10 − 1.5x","var": "the input","why": "Function B starts at 10 and goes down 1.5 each time, so it is y = 10 − 1.5x. The same output means the two rules are equal.","story": [["y = 0.5x + 6","0.5x + 6"],["Start at 10","10"],["decrease by 1.5","1.5x"]]},"8.16-10": {"why": "The account starts at §50 and goes up §20 every week.","story": [["starts with §50","50"],["§20 each week","20"]],"line": {"m": "20","b": "50","ask": "mb","mWhy": "§20 each week is the rate of change.","bWhy": "§50 at the start is the initial value."}},"8.16-11": {"why": "The rate of change is m and the initial value is b.","story": [["rate of change of 4","4"],["initial value of −6","−6"]],"line": {"m": "4","b": "−6","mWhy": "The rate of change is m, so m = 4.","bWhy": "The initial value is b, so b = −6."}},"8.16-14": {"why": "Each time and amount is a point (hours, gallons).","story": [["After 2 hours","2"],["8,500 gallons","8500"],["After 6 hours","6"],["5,500 gallons","5500"]],"line": {"pts": [["2","8500"],["6","5500"]],"ask": "m","end": "It's negative, so the pool loses 750 gallons each hour."}},"8.16-15": {"why": "Each number of guests and cost is a point (guests, cost).","story": [["20 guests","20"],["§750","750"],["50 guests","50"],["§1,500","1500"]],"line": {"pts": [["20","750"],["50","1500"]],"v": "g","fy": "C(g)"}},"8.16-17": {"why": "Each time and altitude is a point (minutes, feet).","story": [["4 minutes","4"],["26,000 feet","26000"],["10 minutes","10"],["17,000 feet","17000"]],"line": {"pts": [["4","26000"],["10","17000"]],"ask": "zero","v": "t","zeroTitle": "Find when the altitude is 0","zeroWhy": "Landing means altitude 0. Set the function equal to 0, add 1500t to both sides, then divide by 1,500."}},"8.25-25": {"expr": "180 − (52 + 71)","why": "The three angles of a triangle add up to 180°. Take the two known angles away from 180.","story": [["52 degrees","52"],["71 degrees","71"]]},"8.25-28": {"expr": "35 + 42","why": "The line through the elbow, parallel to the walls, splits the elbow into two pieces. Each piece is an alternate interior angle with one wall, so the pieces are 35° and 42°. Add them.","story": [["35-degree","35"],["42-degree","42"]]},"AlgI.11-01": {"eq": "60 − 4d < 20","var": "the number of days","why": "You start with §60 and lose §4 each day, so after d days you have 60 − 4d. That has to be less than §20.","story": [["§60","60"],["§4 a day","−4d"],["less than §20","20"]]},"AlgI.11-07": {"quad": "w(w + 3) = 40","var": "the width","keep": "positive","why": "Call the width w. The length is 3 more, w + 3. Area is width × length, so w(w + 3) = 40.","story": [["3 more than its width","w + 3"],["area is 40","40"]],"keepWhy": "A width can't be negative, so w = 5. The length is 5 + 3 = 8."},"AlgI.11-08": {"grow": "200 · 2^t = 3200","var": "the number of years","why": "Doubling every year multiplies by 2 each year, so after t years the population is 200 · 2^t. It has to reach 3,200.","story": [["200","200"],["doubles every year","2"],["3,200","3200"]]},"AlgI.11-09": {"eq": "82 + 91 + x ≥ 264","var": "the 3rd test score","why": "An average of at least 88 over 3 tests means the 3 scores add up to at least 3 × 88 = 264.","story": [["82","82"],["91","91"],["average of at least 88","264"]]},"AlgI.11-10": {"write": "45 + 12w = 165","var": "the number of weeks","why": "She starts with §45 and adds §12 each week, so after w weeks she has 45 + 12w. That has to reach §165.","story": [["has §45","45"],["§12 per week","12w"],["costs §165","165"]]},"AlgI.11-11": {"write": "700 + 60b ≤ 2500","var": "the number of boxes","why": "The load is the 700-pound crate plus 60 pounds for each box, 60b. At most 2,500 means it can equal 2,500 or be less: ≤.","story": [["700-pound crate","700"],["60 pounds each","60b"],["at most 2,500 pounds","2500"]]},"AlgI.11-12": {"write": "100(2)^t = 3200","var": "the number of hours","why": "Doubling every hour multiplies by 2 each hour, so after t hours there are 100 × 2 × 2 × … = 100(2)^t bacteria. That has to reach 3,200.","story": [["100 bacteria","100"],["doubles","2"],["3,200","3200"]]},"AlgI.11-13": {"quad": "w(w + 5) = 84","var": "the width","keep": "positive","why": "The width is w, so the length is w + 5. Area is width × length, so w(w + 5) = 84.","story": [["5 meters longer than its width w","w + 5"],["84 square meters","84"]],"keepWhy": "A width can't be negative, so the width is 7 meters."},"AlgI.11-14": {"write": "|w − 500| ≤ 4","var": "the actual weight","why": "How far w is from 500 is |w − 500|. Within 4 grams means that distance is 4 or less.","story": [["target weight of 500 grams","500"],["within 4 grams","4"]]},"AlgI.11-15": {"write": "20000(0.9)^t = 14580","var": "the number of years","why": "Losing 10% each year leaves 90% of the value: 1 − 0.10 = 0.9. After t years the car is worth 20000(0.9)^t, and that has to equal §14,580.","story": [["§20,000","20000"],["loses 10%","0.9"],["§14,580","14580"]]},"AlgI.11-16": {"quad": "−16t² + 96t + 40 = 148","var": "the time in seconds","why": "The height is −16t² + 96t + 40. Set it equal to 148 and solve for t.","story": [["h = −16t² + 96t + 40","−16t² + 96t + 40"],["148 feet","148"]],"keepWhy": "Both times work. The rocket passes 148 feet on the way up, then again on the way down.","labels": ["on the way up","on the way down"]},"AlgI.11-17": {"eq": "|L − 24| > 0.15","var": "the rod's length","why": "How far L is from 24 is |L − 24|. A rejected rod is more than 0.15 cm away, so |L − 24| > 0.15.","story": [["a length of 24 cm","24"],["more than 0.15 cm","0.15"]]},"AlgI.11-18": {"eq": "300 + 8n > 1100","var": "the number of students","why": "Hall A costs 300 + 8n. Hall B is cheaper when Hall A costs more than §1,100.","story": [["§300","300"],["§8 per student","8n"],["§1,100","1100"]],"end": "n is a whole number of students, up to 150. So Hall B is cheaper for 101 to 150 students."}};
